#!/usr/bin/env node
// Parity check: the JS range checks ($lib/cfpsRangeChecks.js) must raise exactly
// the flags the real autonomous-cfps Python raises. The fixtures (recipes + the
// Python's flags) are regenerated by `npm run sync:cfps`.
//
//   node tools/check-cfps-range-parity.mjs

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const REPO_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const fixtures = JSON.parse(fs.readFileSync(path.join(REPO_ROOT, 'tools/fixtures/cfps-range-checks.fixtures.json'), 'utf8'));

// cfpsRangeChecks.js imports the generated JSON the Vite way (no import
// attribute), which plain Node rejects — load a copy with the import rewritten.
const src = fs.readFileSync(path.join(REPO_ROOT, 'src/lib/cfpsRangeChecks.js'), 'utf8')
  .replace("from './cfpsReagentSpec.generated.json';", "from './cfpsReagentSpec.generated.json' with { type: 'json' };");
const tmp = path.join(REPO_ROOT, 'src/lib/.cfpsRangeChecks.parity.mjs');
fs.writeFileSync(tmp, src);
let evaluateRangeChecks;
try {
  ({ evaluateRangeChecks } = await import(pathToFileURL(tmp).href));
} finally {
  fs.unlinkSync(tmp);
}

const close = (a, b) => (a == null || b == null ? a === b : Math.abs(a - b) <= 1e-9 * Math.max(1, Math.abs(a), Math.abs(b)));
let failures = 0;
for (const fx of fixtures) {
  const got = evaluateRangeChecks(fx.reagent_list, { policy: 'autonomous-cfps' }).flags;
  const want = fx.flags;
  const same =
    got.length === want.length &&
    got.every((g, i) =>
      g.component === want[i].component &&
      g.kind === want[i].kind &&
      g.band === want[i].band &&
      g.message === want[i].message &&
      close(g.ratio, want[i].ratio)
    );
  if (!same) {
    failures++;
    if (failures <= 5) {
      console.error(`✗ ${fx.label}`);
      console.error('  python:', JSON.stringify(want.map(({ component, kind, band, message, ratio }) => ({ component, kind, band, message, ratio }))));
      console.error('  js:    ', JSON.stringify(got.map(({ component, kind, band, message, ratio }) => ({ component, kind, band, message, ratio }))));
    }
  }
}
const flagged = fixtures.filter((f) => f.flags.length).length;
if (failures) {
  console.error(`\n${failures} of ${fixtures.length} fixtures differ from autonomous-cfps.`);
  process.exit(1);
}
console.log(`✓ ${fixtures.length} fixtures (${flagged} with flags) match autonomous-cfps exactly.`);
